# rule: for each 5-shape, fill interior (0s enclosed by 5s) with 2; gap in top edge -> beam up one, then left to edge
def transform(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    # find shapes as connected comps of 5
    seen=set(); comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==5 and (i,j) not in seen:
                stack=[(i,j)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==5: stack.append((ny,nx))
                comps.append(comp)
    for comp in comps:
        ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
        y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        # interior: 0-cells in bbox
        inter=[(i,j) for i in range(y0,y1+1) for j in range(x0,x1+1) if g[i][j]==0]
        for i,j in inter: g[i][j]=2
        # gap: 0 in top row of bbox
        gaps=[j for j in range(x0,x1+1) if g[y0][j]==0]
        for jg in gaps:
            r=y0-1
            if r>=0:
                j=jg
                while j>=0:
                    g[r][j]=2; j-=1
    return g
