def bbox(cells):
    """The (top, left, bottom, right) bounding box of a list of (row, col) cells."""
    ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
    return min(ys), min(xs), max(ys), max(xs)

def fill_interior(grid, comp, color, new):
    """Inside a component's bounding box, recolor every cell of `color` that is not on the box border."""
    y0, x0, y1, x1 = bbox(comp)
    g = [row[:] for row in grid]
    for i in range(y0 + 1, y1):
        for j in range(x0 + 1, x1):
            if g[i][j] == color:
                g[i][j] = new
    return g

def beam_from_cells(grid, cells, new, direction='left'):
    """From each cell, recolor a ray of `new` one row above it going in `direction` until the grid edge."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    for i, j in cells:
        r = i - 1
        if r < 0:
            continue
        j = j + (-1 if direction == 'left' else 1)
        while 0 <= j < w:
            g[r][j] = new
            j += -1 if direction == 'left' else 1
    return g

def recolor(grid, cells, new):
    """Recolor the given (row, col) cells to `new`."""
    g = [row[:] for row in grid]
    for i, j in cells:
        g[i][j] = new
    return g
